import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"12 周智能合约学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1791601077000}'),o={name:"roadmap.md"};function n(s,t,i,l,h,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="_12-周智能合约学习路线" tabindex="-1">12 周智能合约学习路线 <a class="header-anchor" href="#_12-周智能合约学习路线" aria-label="Permalink to &quot;12 周智能合约学习路线&quot;">​</a></h1><blockquote><p>适合有 Python/Flask、数据库、API、Linux/Git 基础，希望从零接触智能合约的开发者。按每天约 1～2 小时规划，<strong>不是学习成效保证</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>周次</th><th>本周主线</th><th>可验收的产物</th></tr></thead><tbody><tr><td>1</td><td>区块链账户、钱包、交易、链、节点与安全边界</td><td>能解释私钥、地址和 EOA；在 Remix 部署 Counter</td></tr><tr><td>2</td><td>Solidity 类型、函数、可见性、状态变量</td><td>Counter 的访问控制与更新事件</td></tr><tr><td>3</td><td>mapping、struct、storage/memory/calldata、事件</td><td>一个带用户余额记录的练习合约</td></tr><tr><td>4</td><td>EVM、Gas、ABI、call、revert、交易原子性</td><td>解码一次调用并说明费用与回滚</td></tr><tr><td>5</td><td>Foundry 工程、forge test、断言与预期回滚</td><td>给 Counter 编写正反向测试</td></tr><tr><td>6</td><td>fuzz、边界、状态机、不变量</td><td>为托管项目列出 5 个不变量</td></tr><tr><td>7</td><td>常见安全风险：重入、权限、拒绝服务、签名</td><td>重入风险对照实验与 CEI 修复</td></tr><tr><td>8</td><td>ERC-20、OpenZeppelin、审批与 allowance</td><td>解释 approve/transferFrom 的风险和用途</td></tr><tr><td>9</td><td>Escrow 项目需求、角色、状态与威胁建模</td><td>合约状态图和权限矩阵</td></tr><tr><td>10</td><td>Escrow 工程实现与事件设计</td><td>本地创建、交付、放款、退款流程</td></tr><tr><td>11</td><td>Escrow 单测、fuzz、Invariant、gas 分析</td><td>自动化测试报告与验收记录</td></tr><tr><td>12</td><td>测试网部署、合约验证、源码审阅、求职复盘</td><td>演示视频/README/架构图/面试问答</td></tr></tbody></table><h2 id="零基础建议-第一周怎么安排每天的学习" tabindex="-1">零基础建议：第一周怎么安排每天的学习？ <a class="header-anchor" href="#零基础建议-第一周怎么安排每天的学习" aria-label="Permalink to &quot;零基础建议：第一周怎么安排每天的学习？&quot;">​</a></h2><p>不要一开始把 12 周的术语全部背下来。第一周只验证三件事：<strong>知道区块链做什么、能操作 Remix VM、能看懂计数器的核心代码。</strong></p><table tabindex="0"><thead><tr><th>学习日</th><th>学什么</th><th>自己动手做什么</th></tr></thead><tbody><tr><td>第 1 天</td><td><a href="/00-start/">00-1 区块链、钱包、交易和 Gas</a></td><td>用自己的话解释六个关键词，不安装软件</td></tr><tr><td>第 2 天</td><td><a href="/00-start/glossary">术语词典</a> 和 <a href="/00-start/environment">Remix 入门前半段</a></td><td>新建文件、编译、在 Remix VM 部署</td></tr><tr><td>第 3 天</td><td><a href="/00-start/environment">Remix 入门后半段</a></td><td>操作 0→1→2，找到 Gas / 交易记录</td></tr><tr><td>第 4 天</td><td><a href="/00-start/backend-map">从 Flask 迁移到链上</a></td><td>画出买家、卖家的权限表</td></tr><tr><td>第 5 天</td><td><a href="/01-solidity/">Solidity 基础</a></td><td>验证非 owner reset 会失败</td></tr><tr><td>第 6 天</td><td>复习并重做前面实验</td><td>不看教程重做一次 Counter</td></tr><tr><td>第 7 天</td><td>补漏与休息</td><td>写一页自己的学习笔记：已懂 / 不懂 / 待练习</td></tr></tbody></table><p>这里的学习日是建议节奏，并非一定要每天完成。<strong>碰到报错先看本节“常见错误”，不要因为某个英文术语不懂就跳到下一章。</strong></p><h2 id="推荐按三条线路并行" tabindex="-1">推荐按三条线路并行 <a class="header-anchor" href="#推荐按三条线路并行" aria-label="Permalink to &quot;推荐按三条线路并行&quot;">​</a></h2><p><strong>概念线（20%）</strong>：区块链和传统后端的不同是什么？谁来执行代码？数据能否删除？</p><p><strong>代码线（50%）</strong>：每个知识点必须能编译、能跑测试、能复现失败；避免只看视频。</p><p><strong>安全线（30%）</strong>：每周至少回答一个问题：没有权限的人能否调用？谁能冻结资金？失败时是否会卡死？</p><h2 id="为什么先选-ethereum-evm-solidity-foundry" tabindex="-1">为什么先选 Ethereum EVM / Solidity / Foundry？ <a class="header-anchor" href="#为什么先选-ethereum-evm-solidity-foundry" aria-label="Permalink to &quot;为什么先选 Ethereum EVM / Solidity / Foundry？&quot;">​</a></h2><p>这是学习主线，不表示其他生态不重要。<strong>先把账户、交易、Gas、合约状态和测试学透</strong>，后续再学 L2、跨链、DeFi、Move/Rust 生态，避免初学期同时切换三种执行模型。</p><h2 id="你的现有后端经验可以迁移" tabindex="-1">你的现有后端经验可以迁移 <a class="header-anchor" href="#你的现有后端经验可以迁移" aria-label="Permalink to &quot;你的现有后端经验可以迁移&quot;">​</a></h2><ul><li>Python 函数与 REST API → Solidity external/public 与 ABI；但调用成本与错误语义不同。</li><li>数据库事务 → EVM 交易原子性；但链上写入昂贵、公开且难以删除。</li><li>JWT/RBAC → 签名与 msg.sender；链上权限一般不能依赖 Web 用户名。</li><li>pytest → Foundry Forge；需要额外的敌手视角与不变量测试。</li><li>Celery 定时任务 → 链上不能自己定时执行，必须由外部交易触发。</li></ul><h2 id="每周验收的方法" tabindex="-1">每周验收的方法 <a class="header-anchor" href="#每周验收的方法" aria-label="Permalink to &quot;每周验收的方法&quot;">​</a></h2><p>完成课程后留三件东西：<strong>可重现命令</strong>、<strong>失败用例</strong>、<strong>一段自己的解释</strong>。完成不等于“读过一遍”，以 <a href="/checklist">验收表</a> 为准。</p>',17)])])}const m=d(o,[["render",n]]);export{c as __pageData,m as default};
